data.minimal_example:
ArLocationWidget(
  annotations: pois,
  annotationWidth: 180,
  annotationHeight: 60,
  annotationViewBuilder: (context, annotation) {
    final poi = annotation as Poi;
    return Card(
      child: ListTile(
        title: Text(poi.name),
        subtitle: Text('${poi.distanceFromUser.round()} m'),
      ),
    );
  },
  onLocationChange: (position) => loadPoisAround(position),
)
